public int active()
{
    int ret = next active();

    if (SysCountryRegionCode::isLegalEntityInCountryRegion([#isoBR]))
    {
        if (TaxBRReformSinief08FiscalNotesFlight::instance().isEnabled())
        {
            SalesParmTable salesParmTable = this.cursor();
            boolean isTotalReturnVisible;
            if (salesParmTable.Ordering == DocumentStatus::Invoice)
            {
                isTotalReturnVisible = salesParmTable.salesTable().SalesType == SalesType::ReturnItem;
            }
            this.object(fieldNum(SalesParmTable, TotalReturn_BR)).visible(isTotalReturnVisible);
        }
        else
        {
            this.object(fieldNum(SalesParmTable, TotalReturn_BR)).visible(false);
        }
    }

    return ret;
}
